#!/bin/bash
set -euo pipefail

# Base version comes from the Info.plist generated by XcodeGen.
BASE_VERSION="${1:?Base version is required}"
VERSION_PATTERN='^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$'
[[ "$BASE_VERSION" =~ $VERSION_PATTERN ]] || { echo "Invalid base version: $BASE_VERSION" >&2; exit 1; }
[[ "${GITHUB_RUN_NUMBER:-}" =~ ^[1-9][0-9]*$ ]] || { echo "Invalid run number" >&2; exit 1; }
[[ "${GITHUB_RUN_ATTEMPT:-}" =~ ^[1-9][0-9]*$ ]] || { echo "Invalid run attempt" >&2; exit 1; }

if [[ "${GITHUB_REF_TYPE:-}" == "tag" ]]; then
  [[ "${GITHUB_REF_NAME:-}" == v* ]] || { echo "Expected vMAJOR.MINOR.PATCH tag" >&2; exit 1; }
  APP_VERSION="${GITHUB_REF_NAME#v}"
  [[ "$APP_VERSION" =~ $VERSION_PATTERN ]] || { echo "Expected vMAJOR.MINOR.PATCH tag" >&2; exit 1; }
  RELEASE_TAG="$GITHUB_REF_NAME"
else
  IFS=. read -r MAJOR MINOR PATCH <<< "$BASE_VERSION"
  APP_VERSION="$MAJOR.$MINOR.$((PATCH + GITHUB_RUN_NUMBER))"
  RELEASE_TAG="v${APP_VERSION}"
fi

BUILD_VERSION="${GITHUB_RUN_NUMBER}.${GITHUB_RUN_ATTEMPT}"
DMG_NAME="Pixon-${APP_VERSION}-build-${BUILD_VERSION}-universal-unsigned.dmg"
printf 'APP_VERSION=%s\nBUILD_VERSION=%s\nRELEASE_TAG=%s\nDMG_NAME=%s\n' \
  "$APP_VERSION" "$BUILD_VERSION" "$RELEASE_TAG" "$DMG_NAME"
